from pathlib import Path
import json,html
root=Path('docs/release/emerald-enterprise');r=json.loads((root/'result.json').read_text());esc=html.escape
before={x['key']:x for x in r['before']};keys=list(dict.fromkeys(x['key'] for x in r['after']));tokens=json.loads((root/'tokens.json').read_text())
style='''*{box-sizing:border-box}body{margin:0;background:#f5f8f6;color:#172c28;font:15px/1.7 system-ui,Tahoma,sans-serif}header,main,footer{max-width:1680px;margin:auto;padding:24px}h1{font-size:clamp(26px,3vw,40px);line-height:1.25}h2{font-size:23px}a{color:#076b59}button,select{font:inherit;min-height:44px;padding:9px;border:1px solid #70887e;border-radius:8px;background:white;color:#172c28}a:focus-visible,select:focus-visible,button:focus-visible,[tabindex]:focus-visible{outline:3px solid #087e68;outline-offset:3px}.notice{padding:16px;background:#edf3ef;border:1px solid #70887e;border-radius:12px}.controls{display:flex;flex-wrap:wrap;gap:16px;position:sticky;top:0;z-index:2;background:#f5f8f6;padding:16px 0}label{display:grid;gap:5px;max-width:100%}select{max-width:100%}.grid{display:grid;grid-template-columns:1fr 1fr 0.55fr;gap:18px}.card{background:white;border:1px solid #70887e;border-radius:12px;min-width:0;overflow:hidden}.card h3{padding:16px;margin:0;font-size:16px}.card img{width:100%;height:650px;object-fit:contain;object-position:top;display:block;background:#edf3ef}.card>a{display:block;padding:12px}.tokens{display:flex;gap:12px;flex-wrap:wrap}.token{background:white;padding:10px;border:1px solid #70887e;border-radius:8px;min-width:180px}.swatch{display:inline-block;width:32px;height:24px;vertical-align:middle;margin-inline-end:10px;border:1px solid #70887e}section{margin-block:30px}.scroll{overflow:auto}table{width:100%;border-collapse:collapse}td,th{padding:10px;text-align:start;border-bottom:1px solid #dee9e3}th{background:#edf3ef}.skip:not(:focus){position:absolute;clip-path:inset(50%);width:1px;height:1px;overflow:hidden}pre{white-space:pre-wrap;overflow-wrap:anywhere}@media(max-width:900px){.grid{grid-template-columns:1fr}.card img{height:600px}header,main,footer{padding:16px}}'''
metrics=f"{len(r['before'])} baseline screenshots · {len(r['after'])} final screenshots · {len(r['scans'])} scoped accessibility scans · {sum(len(x['failures']) for x in r['contrast'])} measured active-text contrast failures"
page='''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>NARVO Emerald Enterprise — local acceptance</title><style>'''+style+'''</style></head><body><a class="skip" href="#main">Skip to comparison</a><header><h1>NARVO Emerald Enterprise</h1><p>Approved Theme B · local implementation for visual acceptance</p><p class="notice">Synthetic fixtures only. No hosted services, financial commands, invitations or deployment. Human visual approval remains pending.</p><nav aria-label="Evidence navigation"><a href="../../ENTERPRISE_THEME_COMPARISON.md#emerald-enterprise-local-implementation">Implementation report</a> · <a href="result.json">Verification results</a> · <a href="inventory.json">Route inventory</a> · <a href="tokens.json">Token map</a></nav></header><main id="main"><section><h2>Before and after</h2><p>English desktop comparisons use equivalent fixture data. Selecting Arabic changes the final desktop image; the baseline remains explicitly English. Mobile evidence is Arabic RTL. Open an image for full-size inspection.</p><div class="controls"><label>Screen or state<select id="screen">'''+''.join(f'<option value="{esc(k)}">{esc(k.replace("-"," ").title())}</option>' for k in keys)+'''</select></label><label>Final desktop language<select id="locale"><option value="en-desktop">English LTR · 1440px</option><option value="ar-desktop">Arabic RTL · 1440px</option></select></label></div><p id="context" aria-live="polite"></p><div class="grid">'''+''.join(f'<article class="card"><h3>{label}</h3><img id="{key}" alt="{label}"><a id="{key}-link">Open full-size {label.lower()}</a></article>' for key,label in [('before','Before · English desktop'),('after','Emerald · desktop'),('mobile','Emerald · Arabic mobile')])+'''</div></section><section><h2>Shared semantic tokens</h2><p>Brand actions, success, warning, danger, information and pending states have separate roles. Financial amounts remain neutral unless their explicit meaning is a favorable/adverse difference.</p><div class="tokens">'''+''.join(f'<div class="token"><span class="swatch" style="background:{v}" aria-hidden="true"></span>{esc(k)}<br><code>{v}</code></div>' for k,v in tokens.items())+'''</div></section><section><h2>Verification and review limits</h2><p>'''+metrics+'''</p><p>Chromium fixture results do not certify complete WCAG compliance. Review exact confirmed findings and incomplete checks below and in the report. Screen-reader, cross-browser, real identity and human visual acceptance remain separate gates.</p><details><summary>Accessibility findings and incomplete checks</summary><pre>'''+esc(json.dumps({'violations':[s for s in r['scans'] if s['violations']],'incomplete':[s for s in r['scans'] if s['incomplete']]},indent=2))+'''</pre></details></section><section><h2>Reviewed screens</h2><div class="scroll" tabindex="0" role="region" aria-label="Route and component inventory"><table><thead><tr><th>Route/state</th><th>Runtime evidence</th></tr></thead><tbody>'''+''.join(f'<tr><td>{esc(k)}</td><td>English desktop; Arabic mobile'+('; Arabic desktop' if any(x['key']==k and x['layout']=='ar-desktop' for x in r['after']) else '')+'</td></tr>' for k in keys)+'''</tbody></table></div></section></main><footer><p>Local visual acceptance only. Hosted activation, release, financial validation and production audit are not performed.</p></footer><script>const data='''+json.dumps({'before':r['before'],'after':r['after']}).replace('<','\\u003c')+''';const screen=document.getElementById('screen'),locale=document.getElementById('locale');function render(){const b=data.before.find(x=>x.key===screen.value),variants=data.after.filter(x=>x.key===screen.value),a=variants.find(x=>x.layout===locale.value)||variants.find(x=>x.layout==='en-desktop'),m=variants.find(x=>x.layout==='ar-mobile');for(const [id,c,phase] of [['before',b,'before'],['after',a,'after'],['mobile',m,'after']]){const img=document.getElementById(id),link=document.getElementById(id+'-link');if(c){const path=phase+'/screenshots/'+c.file;img.src=path;img.alt=screen.value+' · '+phase+' · '+c.layout;img.hidden=false;link.href=path;link.textContent='Open full-size '+img.alt}else{img.hidden=true;link.removeAttribute('href');link.textContent='No capture at this layout'}}document.getElementById('context').textContent=screen.options[screen.selectedIndex].text+' · '+(a?.layout||'')+(a?.layout!==locale.value?' · Arabic desktop not captured for this supplemental state; English shown.':'')}screen.addEventListener('change',render);locale.addEventListener('change',render);render();</script></body></html>'''
